var current=baseline;int writes=0;ConfigurationSubscriptionDestination? lastDestination=null;WorkflowValueReference? lastReference=null;
void Apply(ConfigurationSubscriptionDestination destination,WorkflowValueReference? reference) {
 writes++;lastDestination=destination;lastReference=reference;
 bool parameter=destination.Domain==ConfigurationSubscriptionDomain.Parameter;
 var list=current.Configuration.Subscriptions.Where(x=>x.NodeId!="target"||x.Target!=destination.Name||x.IsParameter!=parameter).ToList();
 if(reference!=null)list.Add(new("target",destination.Name,parameter,reference));
 current=current with {Configuration=current.Configuration with {Subscriptions=list},Connections=parameter?current.Connections:current.Connections.Where(x=>x.ToNode!="target"||x.ToPort!=destination.Name).ToArray()};
