Check(service.Bind(D("F"),O("sibling")).Status==ConfigurationSubscriptionStatus.Failed&&writes==before,"unrelated earlier source rejected");Check(service.Bind(D("F"),O("down")).Status==ConfigurationSubscriptionStatus.Failed,"successor rejected");Check(service.Bind(D("F"),O("target")).Status==ConfigurationSubscriptionStatus.Failed,"self rejected");
Check(service.Bind(D("F"),O(procedure:"other")).Status==ConfigurationSubscriptionStatus.Unsupported,"cross procedure unsupported");Check(service.Bind(D("F"),new(new ConfigurationGlobalReference("g","float"),ConfigurationSubscriptionIndex.All)).Status==ConfigurationSubscriptionStatus.Unsupported,"global unsupported");Check(service.Bind(D("F"),O() with {Index=ConfigurationSubscriptionIndex.At(0)}).Status==ConfigurationSubscriptionStatus.Unsupported,"literal index unsupported");
Check(service.Bind(D("F"),O(port:"Int",native:"int")).Status==ConfigurationSubscriptionStatus.Failed,"native type filter not broadened");Check(service.Bind(D("I","int"),O()).Status==ConfigurationSubscriptionStatus.Failed,"number cannot flow to integer");Check(service.Bind(D("F"),O(native:"double")).Status==ConfigurationSubscriptionStatus.Failed,"forged native width cannot bypass filter");
Check(service.Bind(D("Promote","float;int"),O(port:"Int",native:"int")).Status==ConfigurationSubscriptionStatus.Available,"explicit AcceptInteger port promotion");
