Check(service.Enumerate(new(D("Img","IMAGE",ConfigurationSubscriptionDomain.Combination),new[]{"IMAGE"})).Status==ConfigurationSubscriptionStatus.Available,"image combination exact framework type");
Check(service.Enumerate(new(D("C","CIRCLE",ConfigurationSubscriptionDomain.Combination),new[]{"CIRCLE"})).Roots.Count==3,"circle combination distinct");
Check(service.Enumerate(new(D("Batch","POINT",ConfigurationSubscriptionDomain.Combination),new[]{"POINT"})).Status==ConfigurationSubscriptionStatus.Unsupported,"numeric array cannot impersonate point");
Check(service.Enumerate(new(D("B","int"),new[]{"int"})).Status==ConfigurationSubscriptionStatus.Unsupported,"boolean native mapping not guessed");
