Check(service.Read(param).Binding==O(),"parameter readback");before=writes;Check(service.Bind(param,C("float","20")).Status==ConfigurationSubscriptionStatus.Failed&&writes==before,"parameter constant range checked");Check(service.Bind(param,C("float","2.5")).Status==ConfigurationSubscriptionStatus.Available,"valid parameter constant");
